def min_operations(n, k):
    a = [0] * n
    k = k % n
    for i in range(n):
        a[i] = a[i] + 1
    product = 1
    for i in range(n):
        product *= a[i]
    if product % k == 0:
        return min(n, k)
    else:
        return 0

