                cookies.append(i * W + j)
    return len(cookies)

def find_minimum_s(coordinates):
    distance = 0
    for i in range(len(coordinates)):
        distance += (coordinates[i][0] - coordinates[i-1][0])**2 + (coordinates[i][1] - coordinates[i-1][1])**2
    penalty = 0
    if len(coordinates) > 1:
        for i in range(1, len(coordinates)):
            if coordinates[i][0] == coordinates[i-1][0] and coordinates[i][1] == coordinates[i-1][1]:
                penalty += 2
            else:
                penalty += 0
    s = distance + penalty
    return s

