def travel_time(N, A, B, C):
    D = {i: 0 for i in range(1, N + 1)}
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            if i != j:
                D[i] += A * (i - j)
                D[j] += B * (i - j) + C
    return min(D.values())

