def ctz(N):
    if N == 0:
        return 0
    elif N == 1:
        return 1
    else:
        return 1 + ctz(N - 1) + ctz(N - 2)

def generate_pyramid_sequence(A):
    max_size = 0
    for i in range(1, len(A)):
        if A[i] > A[i-1]:
            max_size = max(max_size, i)
        elif A[i] < A[i-1]:
            max_size = max(max_size, i)
        else:
            break
    return max_size

def winner(n):
    total_score = 0
    for i in range(1, n + 1):
        total_score += i
        if total_score == n:
            return "Draw"
    return "Takahashi"

