def find_most_frequent_character(s):
    if not s:
        print("Error: Invalid input")
        return
    if not s.isalpha():
        print("Error: Invalid input")
        return
    frequency = {}
    for char in s:
        if char not in frequency:
            frequency[char] = 1
        else:
            frequency[char] += 1
    most_frequent_char = max(frequency, key=frequency.get)
    print(most_frequent_char)

