def repaint_grid(H, W, M):
    T = [0] * (H * W)
    X = [0] * (H * W)
    for i in range(M):
        T[i * H + A[i]] = 1
        X[i * H + A[i]] = X[i * H + A[i]] + 1
    K = 0
    for i in range(1, H * W + 1):
        if X[i] > 0:
            K += 1
    return K + 1

def find_sum_of_non_appearing_integers(A, K):
    if len(A) == 0:
        return 0
    if len(A) == 1:
        return A[0]
    if A[0] < K:
        return find_sum_of_non_appearing_integers(A[1:], K - A[0])
    return find_sum_of_non_appearing_integers(A[1:], K)

def divide_and_print_quotients(A, K):
    quotients = []
    for i in range(len(A)):
        if A[i] % K == 0:
            quotients.append(A[i] // K)
    return sorted(quotients)
