def farthest_point(points):
    farthest_point = None
    for i in range(len(points)):
        distance = [abs(x - points[i][0]) + abs(y - points[i][1]) for x, y in zip(points[i][0], points[i][1])]
        if distance.index(min(distance)) == i:
            farthest_point = i
    return farthest_point

