def generate_function(N, M):
    def generate_function_helper(N, M):
        if N > M:
            return 0
        if N == M:
            return 1
        if N < M:
            return generate_function_helper(N - 1, M) + generate_function_helper(N, M - 1)
        return generate_function_helper(N - 1, M - 1) + generate_function_helper(N - 1, M)
    return generate_function_helper(N, M)
