def find_max_degree_of_freedom(grid):
    degree_of_freedom = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '.':
                continue
            if grid[i][j] == '#':
                degree_of_freedom += 1
    return max(degree_of_freedom, key=degree_of_freedom)

