        print("Invalid line number. Please enter a valid line number between 1 and N.")
        return False
    if train < 1 or train > N:
        print("Invalid train number. Please enter a valid train number between 1 and N.")
        return False
    if station < 1 or station > N:
        print("Invalid station number. Please enter a valid station number between 1 and N.")
        return False
    if line - train > 0 and line - train < N:
        print("Invalid travel time. Please enter a valid travel time between 1 and N.")
        return False
    return True

def check_train(train, station):
    if train < 1 or train > N:
        print("Invalid train number. Please enter a valid train number between 1 and N.")
        return False
    if station < 1 or station > N:
        print("Invalid station number. Please enter a valid station number between 1 and N.")
        return False
    return True

