def f(A_1, A_2):
    return A_1 + A_2

def sum_f(A):
    return sum(f(A_i, A_j) for A_i, A_j in zip(A, A[1:]))

def main():
    N = int(input("N: "))
    A = list(map(int, input("A: ").split()))
    print(sum_f(A))

