def check_consecutive_elements(A, B):
    if len(A) != len(B):
        return False
    if not A or not B:
        return False
    A.sort()
    B.sort()
    return A == B

def identify_culprit(witnesses):
    if len(witnesses) == 2:
        if witnesses[0] != witnesses[1]:
            return -1
        else:
            return witnesses[0]
    else:
        return -1

def intersect_intervals(intervals):
    intersections = set()
    for i, j in combinations(intervals, 2):
        if i < j:
            intersections.add((i, j))
    return len(intersections)

