def mark_array(nums, queries):
    if not nums:
        return []
    if not queries:
        return [sum(nums)]

    def mark_element(nums, queries, index, k):
        if index == k:
            return nums
        if nums[index] == nums[k]:
            return nums

        if nums[index] < nums[k]:
            return mark_element(nums, queries, index + 1, k)
        else:
            return mark_element(nums, queries, k + 1, k)

    return [mark_element(nums, queries, i, k) for i, (k, queries) in enumerate(queries)]
nums = [1, 2, 2, 1, 2, 3, 1]
queries = [[1, 2], [3, 3], [4, 2]]

print(mark_array(nums, queries))

